    // Chapter 1: getting_started
    'manual_ch_getting_started_title' => '1. Getting Started, Dashboard & Platform Navigation',
    'manual_ch_getting_started_badge' => 'Platform Foundation',
    'manual_ch_getting_started_summary' => 'Comprehensive guide for initial login, navigating dashboard widgets, real-time metrics, language toggle, and platform architecture.',
    'manual_ch_getting_started_purpose' => 'The Madina Natural Care Enterprise Portal serves as the centralized digital infrastructure connecting Dealers, Sub-Dealers, Operating Staff, and Executive Leadership. It automates wholesale procurement, commission distribution, logistics dispatches, earnings payouts, and genealogy network trees.',
    'manual_ch_getting_started_why' => 'Eliminates manual bookkeeping friction, financial opacity, and payout delays by providing an automated, real-time ledger where every transaction has an unalterable audit trail ensuring transparency for all stakeholders.',
    'manual_ch_getting_started_s1' => 'Enter your registered 11-digit mobile number and secure password, then click the "Login" button.',
    'manual_ch_getting_started_s2' => 'Upon successful authentication, complete the interactive onboarding live tour to understand the role and location of each dashboard widget.',
    'manual_ch_getting_started_s3' => 'Review top-level real-time counters displaying total earned commissions, available wallet balance, pending orders, and active rank.',
    'manual_ch_getting_started_s4' => 'Use the left-hand collapsible navigation sidebar to directly access Catalog, Orders, Deliveries, Commissions, Network, and Business Reports.',
    'manual_ch_getting_started_s5' => 'Toggle between Bengali and English interfaces using the language selector on the top header, and customize your visual theme with Dark/Light mode.',
    'manual_ch_getting_started_s6' => 'If the system presents a "Prerequisite Checklist" when accessing any module, satisfy the pending steps first (such as KYC or verifying orders).',
    'manual_ch_getting_started_out1' => 'A cryptographic session token is minted and the role-tailored dashboard layout loads with appropriate capabilities.',
    'manual_ch_getting_started_out2' => 'Dashboard financial metric cards synchronize instantly with the underlying double-entry ledger database.',
    'manual_ch_getting_started_out3' => 'System audit trail logs the authenticated login event along with IP address and device fingerprinting metadata.',
    'manual_ch_getting_started_rule1' => 'Only authorized devices are permitted per active session; anomalous concurrent logins trigger immediate automated security review flags.',
    'manual_ch_getting_started_rule2' => 'Account tier role (Dealer vs Sub-Dealer) is strictly managed by administrative oversight.',
    'manual_ch_getting_started_rule3' => 'Inactive or suspended partner accounts are automatically blocked from submitting orders or withdrawing wallet funds.',
    'manual_ch_getting_started_t1' => 'If you skip the first-visit onboarding tour, you can relaunch it at any moment by clicking "User Manual & Live Tour" in the sidebar.',
    'manual_ch_getting_started_t2' => 'When accessing from smartphones or tablets, tap the top-left hamburger menu button to reveal the collapsible navigation drawer.',
    'manual_ch_getting_started_warn1' => 'Never share your login password or SMS one-time passcode (OTP) with anyone, including company staff.',
    'manual_ch_getting_started_warn2' => 'Always click Logout from your user profile before leaving shared workstations or public internet browsers.',
    'manual_ch_getting_started_q1' => 'How do I recover my account if I forgot my password?',
    'manual_ch_getting_started_a1' => 'Click "Forgot Password" on the login screen, enter your registered mobile number, verify the SMS OTP, and establish a new secure password.',
    'manual_ch_getting_started_q2' => 'Are dashboard balances and figures updated in real-time?',
    'manual_ch_getting_started_a2' => 'Yes, every approved purchase, verified payment claim, and commission allocation updates the ledger and dashboard counters in real time.',
    // Chapter 2: profile_security
    'manual_ch_profile_security_title' => '2. Profile Management, Digital ID Card & Shop Verification',
    'manual_ch_profile_security_badge' => 'Identity & Credentials',
    'manual_ch_profile_security_summary' => 'Manage verified identity details, shop physical address, NID/BDRIS verification, official Madina Partner ID card PDF, and promotional join posters.',
    'manual_ch_profile_security_purpose' => 'Serves as the authoritative registry of verified personal credentials, national identity records (NID/BDRIS), physical shop locations, and financial contact numbers. Enables generation of cryptographic Partner ID cards and QR-branded promotional posters.',
    'manual_ch_profile_security_why' => 'Mandatory KYC/AML compliance, preventing territorial disputes, and guaranteeing that payout disbursements reach the legitimate owner of the registered dealership.',
    'manual_ch_profile_security_s1' => 'Navigate to "Profile" under the Account navigation group in the left sidebar.',
    'manual_ch_profile_security_s2' => 'Confirm and update your full legal name, secondary contact phone, email address, national identity (NID), and physical shop address.',
    'manual_ch_profile_security_s3' => 'Upload a clear passport-sized photograph and shop storefront signboard image for verification.',
    'manual_ch_profile_security_s4' => 'Click "Save Profile" to commit changes; a green confirmation notification confirms successful synchronization.',
    'manual_ch_profile_security_s5' => 'Scroll to the bottom of the Profile page and click "Download Official Partner ID Card" to generate a tamper-evident PDF credential.',
    'manual_ch_profile_security_s6' => 'Click "Download Join Poster" to obtain a print-ready promotional marketing flyer embedded with your personal referral QR code.',
    'manual_ch_profile_security_out1' => 'Database profile fields update and partner verification state changes to KYC Verified.',
    'manual_ch_profile_security_out2' => 'A vectorized official ID card PDF renders containing the cryptographic QR code, assigned place code, and registration identifier.',
    'manual_ch_profile_security_out3' => 'Join poster compiles embedding your direct referral link inside the high-resolution scannable QR code.',
    'manual_ch_profile_security_rule1' => 'Primary registered mobile numbers can only be altered through formal administrative support verification.',
    'manual_ch_profile_security_rule2' => 'One national identity number cannot be utilized to operate duplicate speculative dealership accounts.',
    'manual_ch_profile_security_rule3' => 'Relocating a physical shop to another administrative Upazila requires formal territorial place code reassignment.',
    'manual_ch_profile_security_t1' => 'Laminate and display your downloaded Madina Partner ID card in your shop front to foster retail customer confidence.',
    'manual_ch_profile_security_t2' => 'Share the digital Join Poster across social media channels so prospective distributors can scan your QR code and enroll directly.',
    'manual_ch_profile_security_warn1' => 'Providing fraudulent NID or identity documentation results in immediate revocation of dealership status and account freezing.',
    'manual_ch_profile_security_warn2' => 'Altering or falsifying the digital PDF credentials constitutes forgery and is legally actionable.',
    'manual_ch_profile_security_q1' => 'Can I update my shop name or commercial address?',
    'manual_ch_profile_security_a1' => 'Yes, shop name and street address can be edited from Profile. If changing Upazila boundaries, request place code update via support.',
    'manual_ch_profile_security_q2' => 'What should I do if the ID Card PDF fails to download?',
    'manual_ch_profile_security_a2' => 'Verify that full name, phone number, and shop location fields are populated. Incomplete profiles cannot compile PDF cards.',
    // Chapter 3: catalog_orders
    'manual_ch_catalog_orders_title' => '3. Product Catalog, Wholesale Procurement & Order Processing',
    'manual_ch_catalog_orders_badge' => 'Wholesale Procurement',
    'manual_ch_catalog_orders_summary' => 'Explore wholesale prices, retail margins (MRP vs Dealer price), add items to procurement cart, submit purchase requests, and access invoices.',
    'manual_ch_catalog_orders_purpose' => 'The core commerce engine enabling wholesale inventory purchasing. Clearly delineates retail MRP versus partner purchase price, allowing multi-product batching into immutable purchase orders with transparent margin previews.',
    'manual_ch_catalog_orders_why' => 'Guarantees direct factory sourcing of genuine health products at institutional wholesale discounts, maximizing retail profitability while generating formal invoices.',
    'manual_ch_catalog_orders_s1' => 'Open the "Catalog" section located under the Commerce navigation module.',
    'manual_ch_catalog_orders_s2' => 'Browse product cards showing SKU, product specifications, stock status, Maximum Retail Price (MRP), partner wholesale cost, and margin.',
    'manual_ch_catalog_orders_s3' => 'Select desired quantities and click "Add to Cart" for each product requirement.',
    'manual_ch_catalog_orders_s4' => 'Open the Cart summary bar to review line-item totals, wholesale discounts, and net payable invoice value.',
    'manual_ch_catalog_orders_s5' => 'Click "Submit Order Request" to execute purchase processing protected by idempotency locks.',
    'manual_ch_catalog_orders_s6' => 'Track your order under "Orders" where the system assigns a unique reference number (e.g., ORD-2026-XXXX) with status "Pending".',
    'manual_ch_catalog_orders_s7' => 'Click the order to review line items and download the provisional invoice PDF bearing the official "PARTNER COPY" watermark.',
    'manual_ch_catalog_orders_out1' => 'An immutable order record is persisted with a cryptographically enforced idempotency key preventing duplicate submissions.',
    'manual_ch_catalog_orders_out2' => 'Payable invoice total registers automatically inside the pending dues ledger pending financial claim clearance.',
    'manual_ch_catalog_orders_out3' => 'Fulfillment operations staff receive immediate dashboard notifications to review stock reservation.',
    'manual_ch_catalog_orders_rule1' => 'Orders cannot exceed verified warehouse inventory allocations.',
    'manual_ch_catalog_orders_rule2' => 'Submitted purchase orders cannot be arbitrarily edited; changes require formal cancellation through support fulfillment desk.',
    'manual_ch_catalog_orders_rule3' => 'Tier-specific wholesale discounts apply automatically according to active commercial policy configurations.',
    'manual_ch_catalog_orders_t1' => 'Use the mobile sticky summary bar at the bottom of the screen for fast checkout during store hours.',
    'manual_ch_catalog_orders_t2' => 'Review the MRP vs Partner Price difference on each product card to calculate potential retail shelf markup.',
    'manual_ch_catalog_orders_warn1' => 'Avoid repeated fast clicks on the order confirmation button; idempotency safety guards are active.',
    'manual_ch_catalog_orders_warn2' => 'Do not promise end-customer delivery timelines until staff confirms warehouse dispatch.',
    'manual_ch_catalog_orders_q1' => 'Why is there a watermark on my invoice copy?',
    'manual_ch_catalog_orders_a1' => 'Partner invoices carry a subtle "PARTNER COPY" watermark to differentiate dealer accounting copies from company tax master prints.',
    'manual_ch_catalog_orders_q2' => 'What if a product displays as "Out of Stock" in Catalog?',
    'manual_ch_catalog_orders_a2' => 'Inquire via support tickets regarding warehouse restock schedules. Order buttons re-enable as soon as branches receive fresh batches.',
    // Chapter 4: deliveries_dues
    'manual_ch_deliveries_dues_title' => '4. Shipment Deliveries, Courier Challan & Due Adjustments',
    'manual_ch_deliveries_dues_badge' => 'Fulfillment & Logistics',
    'manual_ch_deliveries_dues_summary' => 'Monitor approved order shipments, courier consignment tracking (Steadfast, Pathao, RedX), delivery challan receipts, and dues ledger balancing.',
    'manual_ch_deliveries_dues_purpose' => 'Manages physical warehouse stock movements, courier waybill consignments, package dispatches, and financial ledger due reconciliation for completed and in-flight orders.',
    'manual_ch_deliveries_dues_why' => 'Prevents transit losses, provides real-time shipment transparency, and reconciles partial payments against accounts receivable so dealers maintain clean financial standing.',
    'manual_ch_deliveries_dues_s1' => 'Open "Deliveries" from the sidebar to inspect in-transit shipments and stock movement records.',
    'manual_ch_deliveries_dues_s2' => 'Locate courier provider details (e.g., Steadfast Courier, Pathao, RedX) and consignment tracking references.',
    'manual_ch_deliveries_dues_s3' => 'Click the tracking link to monitor external courier transit milestones from warehouse departure to destination hub.',
    'manual_ch_deliveries_dues_s4' => 'Upon delivery arrival, verify tamper-evident packaging tape seals before signing the courier receipt challan.',
    'manual_ch_deliveries_dues_s5' => 'Open "Dues" to inspect outstanding balances detailing total invoice values, verified payments, and remaining balances.',
    'manual_ch_deliveries_dues_s6' => 'To settle remaining dues, submit payment claims directly against the order using the designated transaction reference.',
    'manual_ch_deliveries_dues_out1' => 'Order state progresses from Dispatched to Delivered with permanent archive records.',
    'manual_ch_deliveries_dues_out2' => 'Verified payment claims debit the outstanding dues ledger, reducing payable amounts to zero.',
    'manual_ch_deliveries_dues_out3' => 'Maintains an unblemished partner credit score facilitating seamless high-volume subsequent orders.',
    'manual_ch_deliveries_dues_rule1' => 'Only orders with verified payment claims or pre-approved institutional credit terms proceed to warehouse packaging.',
    'manual_ch_deliveries_dues_rule2' => 'Damaged packages must be refused or endorsed on the physical delivery challan with photographic evidence filed in Support.',
    'manual_ch_deliveries_dues_rule3' => 'Payment claims require authentic banking or mobile financial service (MFS) transaction references.',
    'manual_ch_deliveries_dues_t1' => 'Retain physical or photographed delivery challans in your store records for monthly audit reconciliation.',
    'manual_ch_deliveries_dues_t2' => 'Review the Dues tab weekly to prevent overdue balances from triggering automatic payout request holds.',
    'manual_ch_deliveries_dues_warn1' => 'Never accept unsealed or visibly tampered courier packages without immediate driver endorsement.',
