    'manual_ch_support_title' => '17. Enterprise Support Helpdesk, Ticket Tracking & Dispute Resolution',
    'manual_ch_support_badge' => 'Support & Dispute Resolution',
    'manual_ch_support_summary' => 'Create categorized support tickets with file attachments for payments, shipping delays, or commission disputes, track responses and SLAs.',
    'manual_ch_support_purpose' => 'The enterprise dispute resolution and customer assistance desk providing systematic, trackable ticketing for operational bottlenecks, payment claims, delivery delays, and commission reconciliations.',
    'manual_ch_support_why' => 'Eliminates lost requests, ensures structured operational accountability, and guarantees that every partner issue is investigated, documented, and resolved under strict governance standards.',
    'manual_ch_support_s1' => 'Navigate to "Help & Support" located under the Account navigation module in the sidebar.',
    'manual_ch_support_s2' => 'Before submitting a ticket, search this User Manual using relevant keywords to see if instant procedural guidance exists.',
    'manual_ch_support_s3' => 'If your issue requires operational intervention, scroll to the "Submit Support Ticket" form.',
    'manual_ch_support_s4' => 'Select the appropriate issue category: Payment Verification, Order Dispatch, Commission Calculation, Technical Issue, or General Inquiry.',
