    'manual_ch_support_s6' => 'Attach supporting files: bank deposit slips, courier delivery receipts, or interface screenshots (.jpg, .png, .pdf).',
    'manual_ch_support_s7' => 'Click "Submit Ticket"; the engine generates a trackable reference ID and queues the case for specialized support staff.',
    'manual_ch_support_s8' => 'Track administrative response updates, staff message replies, and resolution lifecycle status (Open, In Review, Resolved).',
    'manual_ch_support_out1' => 'A ticket is persisted and dispatched into the appropriate departmental queue (Finance or Fulfillment) based on category.',
    'manual_ch_support_out2' => 'When support staff post investigation notes or solutions, the partner receives immediate in-app and notification alerts.',
    'manual_ch_support_out3' => 'Upon successful dispute reconciliation, the case closes with archived resolution notes preserving complete history.',
    'manual_ch_support_rule1' => 'Creating redundant duplicate tickets for the same underlying issue is prohibited; reply to existing open ticket threads.',
    'manual_ch_support_rule2' => 'Unprofessional or abusive language within formal tickets violates platform terms of service.',
    'manual_ch_support_rule3' => 'Payment and logistics escalation tickets process under expedited priority during corporate operational hours.',
    'manual_ch_support_t1' => 'Include specific transaction references, invoice IDs, and exact timestamps to accelerate operational resolution.',
    'manual_ch_support_t2' => 'Attach clear, uncropped screenshots showing error messages or bank debit notifications for immediate diagnosis.',
    'manual_ch_support_warn1' => 'Uploading forged banking receipts into support threads constitutes fraud and causes permanent dealership revocation.',
    'manual_ch_support_warn2' => 'Mark resolved issues closed to maintain a clean active ticket overview.',
    'manual_ch_support_q1' => 'What is the standard response time for support tickets?',
